#include "common.hpp"
struct Old{L i=0,epoch=0;Gate g{};};
int main(int argc,char**argv){assert(argc==3);Reader r(argv[1]);L N=r.counts[0];vector<unsigned char> edit(N);unordered_map<L,Old> ccx,ccz;ccx.reserve(65536);ccz.reserve(65536);vector<L> rd(r.Q),wr(r.Q),kill(r.Q),bw(r.B);L epoch=1,barrier=0,fold=0,cancel=0,zfold=0,zcancel=0;vector<pair<L,pair<U,U>>> inserted;
 auto R=[&](U q,L i){rd[q]=i+1;};auto W=[&](U q,L i){wr[q]=i+1;};auto K=[&](U q,L i){rd[q]=wr[q]=kill[q]=i+1;};
 auto same=[&](Old const&o,Gate g,L i){return o.epoch==epoch&&o.i>=barrier&&o.i<i&&(!(g.op&128)||bw[g.cond]<=o.i);};
 auto gkey=[](Gate g,U x,U y){return (L((g.op&128)?g.cond+1:0)<<20)|(L(x)<<10)|y;};
 for(L i=0;i<N;i++){Gate g=r.read(i);int o=g.op&127;U a=g.a,b=g.b,t=g.t;if(g.op==129||o==1){epoch++;continue;}bool done=false;
 if(o==49&&a!=b&&a!=t&&b!=t){for(U u:{a,b}){L k=gkey(g,t,u);auto it=ccx.find(k);if(it==ccx.end())continue;Old h=it->second;if(!same(h,g,i)||rd[t]>h.i||kill[t]>h.i||wr[h.g.a]>h.i||wr[h.g.b]>h.i)continue;U v=h.g.a==u?h.g.b:h.g.a, z=a==u?b:a;edit[h.i]=1;if(v==z){edit[i]=1;cancel+=2;}else{edit[i]=2;inserted.push_back({i,{v,z}});fold++;}barrier=i+1;done=true;break;}if(!done){if(ccx.size()>200000)ccx.clear();for(U u:{a,b})ccx[gkey(g,t,u)]={i,epoch,g};}}
 if(o==48&&a!=b&&a!=t&&b!=t){array<U,3> A{a,b,t};sort(A.begin(),A.end());for(int j=0;j<3;j++){U x=A[(j+1)%3],y=A[(j+2)%3];if(x>y)swap(x,y);L k=gkey(g,x,y);auto it=ccz.find(k);if(it==ccz.end())continue;Old h=it->second;if(!same(h,g,i)||wr[h.g.a]>h.i||wr[h.g.b]>h.i||wr[h.g.t]>h.i)continue;U v=h.g.a!=x&&h.g.a!=y?h.g.a:(h.g.b!=x&&h.g.b!=y?h.g.b:h.g.t),z=A[j];edit[h.i]=1;if(v==z){edit[i]=1;zcancel+=2;}else{edit[i]=2;inserted.push_back({i,{v,z}});zfold++;}barrier=i+1;done=true;break;}if(!done){if(ccz.size()>200000)ccz.clear();for(int j=0;j<3;j++){U x=A[(j+1)%3],y=A[(j+2)%3];if(x>y)swap(x,y);ccz[gkey(g,x,y)]={i,epoch,g};}}}
 switch(o){case 17:W(a,i);break;case 18:case 80:K(a,i);break;case 16:R(a,i);break;case 33:R(a,i);W(b,i);break;case 32:R(a,i);R(b,i);break;case 34:K(a,i);K(b,i);break;case 49:R(a,i);R(b,i);W(t,i);break;case 48:R(a,i);R(b,i);R(t,i);break;case 50:R(a,i);K(b,i);K(t,i);break;default:break;}if(o==64||o==65||o==66||o==80)bw[g.bit]=i+1;
 }
 r.reset();Writer w(r,r.B);L paid=0;size_t j=0;ofstream log(string(argv[2])+".edits.tsv");for(L i=0;i<N;i++){Gate g=r.read(i);int o=g.op&127;if(edit[i]==1){log<<i<<"\tdrop\t"<<int(g.op)<<"\n";continue;}if(edit[i]==2){assert(j<inserted.size()&&inserted[j].first==i);auto [v,z]=inserted[j++].second;Gate cx{(unsigned char)(33|(g.op&128)),v,z,0,0,g.cond};w.put(cx);w.put(g);w.put(cx);log<<i<<"\tfold\t"<<v<<"\t"<<z<<"\n";}else w.put(g);if(o==48||o==49||o==50)paid++;}assert(j==inserted.size());w.write(argv[2]);cerr<<"before "<<N<<" after "<<w.ops.size()<<" paid "<<paid<<" CCX_fold "<<fold<<" CCX_cancel "<<cancel<<" CCZ_fold "<<zfold<<" CCZ_cancel "<<zcancel<<"\n";
}